<?php
namespace App\Support;
use App\Models\{User,Apprentice,EmployerApprenticeGrant as Grant,ReviewAppointment as Appointment,ReviewAppointmentParty as Party,ReviewAppointmentResponse as Response,TrainingSession,ProgressReviewDraft};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Carbon\Carbon;
class ReviewAppointments {
 public const ROLES=['apprentice'=>'Apprentice','employer'=>'Employer representative','host'=>'GTA review host'];
 public const CHOICES=['Available','Change requested','Cannot attend'];
 public const MODES=['Training centre','Workplace','Online','Phone'];
 public static function fail(string $m='Appointment, authority or source changed. Reload and check the current named participants.'):never {throw ValidationException::withMessages(['appointment'=>$m]);}
 public static function staff(User $u,Apprentice $a):bool {return SignedReviews::allowed($u,$a);}
 public static function seal(User $u):string {return ReviewedImports::hash($u->only(['id','name','email','active','role','record_version','auth_version','email_verified_at']));}
 public static function actor(User $u,int $auth):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->auth_version===$auth,403);return $u;}
 public static function event(Appointment $p,User $u,string $event,array $data=[]):void {DB::table('review_appointment_events')->insert(['appointment_id'=>$p->id,'actor_id'=>$u->id,'event'=>$event,'record_version'=>$p->version,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function basis(Apprentice $profile,int $grantId,int $hostId,bool $lock=false):array {
  $a=Apprentice::whereKey($profile->id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$g=Grant::whereKey($grantId)->when($lock,fn($q)=>$q->lockForUpdate())->first();$learner=$a->user_id?User::find($a->user_id):null;$employer=$g?User::find($g->user_id):null;$host=User::find($hostId);
  if(!$g||!EmployerActions::valid($g,$a)||!$learner||!$learner->active||$learner->role!=='apprentice'||!$learner->email_verified_at||Apprentice::where('user_id',$learner->id)->count()!==1||!filter_var($a->email,FILTER_VALIDATE_EMAIL)||strtolower(trim($a->email??''))!==strtolower(trim($learner->email))||!$host||!$host->active||!$host->email_verified_at||!(LearningAccess::tutor($host,$a)||StaffDuties::assigned($host,$a,'mentor'))){self::fail('Choose current verified individual learner/employer accounts and an assigned eligible Tutor or Learning & Progress Mentor host. Employer workplace access is not review-signing authority.');}
  $people=['apprentice'=>$learner,'employer'=>$employer,'host'=>$host];if(count(array_unique(array_map(fn($u)=>$u->id,$people)))!==3){self::fail('Use three distinct individual accounts.');}$parties=[];foreach($people as$role=>$u){if(!$u||!$u->active||!$u->email_verified_at||User::whereRaw('LOWER(email) = ?',[strtolower(trim($u->email))])->count()!==1){self::fail('Participant mailbox/account is ambiguous or unconfirmed.');}$parties[$role]=['id'=>$u->id,'name'=>$u->name,'identity'=>self::seal($u)];}
  return ['apprentice_id'=>$a->id,'reference'=>$a->reference,'name'=>trim($a->first_name.' '.$a->last_name),'profile_hash'=>ElectronicReviews::profile($a),'grant_id'=>$g->id,'grant_hash'=>ElectronicReviews::grantHash($g),'host_id'=>$host->id,'host_duty_hash'=>ReviewedImports::hash(['tutor'=>LearningAccess::tutor($host,$a),'mentor'=>StaffDuties::assigned($host,$a,'mentor'),'seal'=>StaffHandover::staffSeal($host)]),'timezone'=>(string)config('app.timezone'),'parties'=>$parties];
 }
 public static function intact(Appointment $p):bool {try{$s=$p->source;return $s&&ReviewedImports::hash($s)===$p->source_hash&&$s['origin_creator']===$p->created_by&&$s['request']===$p->request_token&&$s['basis']['apprentice_id']===$p->apprentice_id&&$s['logistics']['start_utc']===$p->starts_at->utc()->toIso8601String()&&$s['logistics']['end_utc']===$p->ends_at->utc()->toIso8601String();}catch(\Throwable){return false;}}
 public static function current(Appointment $p,bool $lock=false):bool {try{if(!self::intact($p)){return false;}$s=$p->source;$a=Apprentice::findOrFail($p->apprentice_id);return ReviewedImports::hash(self::basis($a,$s['basis']['grant_id'],$s['basis']['host_id'],$lock))===ReviewedImports::hash($s['basis']);}catch(\Throwable){return false;}}
 private static function logistics(array $d):array {
  if(!in_array($d['mode'],self::MODES,true)||!is_string($d['place'])||trim($d['place'])===''||mb_strlen($d['place'])>500||preg_match('/[\x00-\x1F\x7F]/u',$d['place'])){self::fail('Use a named meeting mode and one safe line of logistics, no passwords or private review/support detail.');}$tz=(string)config('app.timezone');try{$from=Carbon::createFromFormat('!Y-m-d H:i',$d['date'].' '.$d['start'],$tz);$to=Carbon::createFromFormat('!Y-m-d H:i',$d['date'].' '.$d['end'],$tz);}catch(\Throwable){self::fail('Use an actual valid date/time in the portal timezone.');}if($from->format('Y-m-d H:i')!==$d['date'].' '.$d['start']||$to->format('Y-m-d H:i')!==$d['date'].' '.$d['end']||!$from->gt(now())||$from->gt(now()->addYear())||$from->diffInMinutes($to,false)<5||$from->diffInMinutes($to,false)>240){self::fail('Book a future 5–240 minute same-day slot within one year; check actual timezone/offset.');}return ['date'=>$d['date'],'start'=>$d['start'],'end'=>$d['end'],'timezone'=>$tz,'start_utc'=>$from->utc()->toIso8601String(),'end_utc'=>$to->utc()->toIso8601String(),'mode'=>$d['mode'],'place'=>trim($d['place'])];
 }
 public static function save(User $actor,int $auth,Apprentice $profile,?Appointment $record,int $version,string $request,array $d):Appointment {
  if(!Str::isUuid($request)){self::fail('Reload a fresh appointment form.');}return DB::transaction(function()use($actor,$auth,$profile,$record,$version,$request,$d):Appointment {$initial=self::basis($profile,(int)$d['grant_id'],(int)$d['host_id']);User::whereIn('id',[$actor->id,...array_column($initial['parties'],'id')])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);$a=Apprentice::whereKey($profile->id)->lockForUpdate()->firstOrFail();abort_unless(self::staff($u,$a),403);$b=self::basis($a,(int)$d['grant_id'],(int)$d['host_id'],true);$l=self::logistics($d);
   $p=$record?Appointment::whereKey($record->id)->lockForUpdate()->firstOrFail():null;
   if(!$p&&($old=Appointment::where('request_token',$request)->lockForUpdate()->first())){if(self::intact($old)&&$old->created_by===$u->id&&$old->source['preparer']['auth_version']===$u->auth_version&&$old->apprentice_id===$a->id&&$old->source['basis']===$b&&$old->source['logistics']===$l){return $old;}self::fail('Request already used; reload before changing the request.');}
   if($p&&(!self::intact($p)||$p->apprentice_id!==$a->id||$p->version!==$version||!in_array($p->state,['Draft','Published'],true)||!$p->starts_at->gt(now()))){self::fail('Only the current future Draft/Published appointment can be rescheduled.');}if(!$p&&$version!==0){self::fail();}if(!$p&&Appointment::where('apprentice_id',$a->id)->whereNotNull('active_slot')->exists()){self::fail('An active draft/appointment already exists; reconcile it before booking another.');}
   $before=$p?['state'=>$p->state,'version'=>$p->version,'source'=>$p->source,'publication'=>$p->publication]:null;$p??=new Appointment(['created_by'=>$u->id,'apprentice_id'=>$a->id,'request_token'=>$request,'version'=>0,'followup_version'=>0]);if(!$p->id){$p->id=(string)Str::uuid();}$p->version++;$s=['origin_creator'=>$p->created_by,'request'=>$p->request_token,'preparer'=>['id'=>$u->id,'auth_version'=>$u->auth_version],'prepared_version'=>$p->version,'basis'=>$b,'logistics'=>$l];$p->source=$s;$p->source_hash=ReviewedImports::hash($s);$p->starts_at=Carbon::parse($l['start_utc']);$p->ends_at=Carbon::parse($l['end_utc']);$p->state='Draft';$p->active_slot=1;$p->publication=null;$p->published_at=null;$p->closure=null;$p->outcome=null;$p->followup=null;$p->save();self::event($p,$u,'draft_saved',['before'=>$before,'source_hash'=>$p->source_hash]);return $p;},3);
 }
 public static function publicationValid(Appointment $p):bool {try{$v=$p->publication;return self::intact($p)&&$v&&$v['source_hash']===$p->source_hash&&$v['version']===$p->source['prepared_version']+1&&$v['at']===$p->published_at?->toIso8601String();}catch(\Throwable){return false;}}
 public static function scheduleVersion(Appointment $p):?int {return self::publicationValid($p)?$p->publication['version']:null;}
 private static function partyProof(Party $r):array {return ['appointment_id'=>$r->appointment_id,'appointment_version'=>$r->appointment_version,'user_id'=>$r->user_id,'role'=>$r->role,'identity_hash'=>$r->identity_hash];}
 public static function partiesValid(Appointment $p):bool {try{$version=self::scheduleVersion($p);if(!$version){return false;}$rows=Party::where('appointment_id',$p->id)->where('appointment_version',$version)->get();return $rows->count()===3&&$rows->pluck('user_id')->unique()->count()===3&&$rows->every(fn($r)=>isset(self::ROLES[$r->role])&&$r->proof===self::partyProof($r)+['source_hash'=>$p->source_hash]&&$p->source['basis']['parties'][$r->role]['id']===$r->user_id&&$p->source['basis']['parties'][$r->role]['identity']===$r->identity_hash);}catch(\Throwable){return false;}}
 public static function published(Appointment $p):bool {return $p->state==='Published'&&self::publicationValid($p)&&self::partiesValid($p)&&$p->version===self::scheduleVersion($p);}
 public static function closureValid(Appointment $p):bool {try{$c=$p->closure;return self::intact($p)&&$p->state==='Cancelled'&&$c&&$c['state']==='Cancelled'&&$c['version']===$p->version&&$c['source_hash']===$p->source_hash;}catch(\Throwable){return false;}}
 public static function visible(User $u,Appointment $p):bool {$a=Apprentice::find($p->apprentice_id);if(!$a||!$u->active){return false;}if(self::staff($u,$a)){return true;}if(!in_array($p->state,['Published','Cancelled','Reported'],true)||!self::current($p)||!self::partiesValid($p)){return false;}if($p->state==='Published'&&!self::published($p)||$p->state==='Cancelled'&&!self::closureValid($p)||$p->state==='Reported'&&!ReviewMeetingFollowup::reported($p)){return false;}return Party::where('appointment_id',$p->id)->where('appointment_version',self::scheduleVersion($p))->where('user_id',$u->id)->exists();}
 public static function clashes(Appointment $p):bool {$ids=array_column($p->source['basis']['parties'],'id');$q=Appointment::where('id','!=',$p->id)->where('state','Published')->where('starts_at','<',$p->ends_at)->where('ends_at','>',$p->starts_at)->when(DB::transactionLevel()>0,fn($q)=>$q->lockForUpdate());foreach($q->get()as$other){if(self::published($other)&&array_intersect($ids,array_column($other->source['basis']['parties'],'id'))){return true;}}return false;}
 public static function publish(User $actor,int $auth,Appointment $record,int $version):void {
  DB::transaction(function()use($actor,$auth,$record,$version):void {$a=Apprentice::whereKey($record->apprentice_id)->lockForUpdate()->firstOrFail();$p=Appointment::whereKey($record->id)->lockForUpdate()->firstOrFail();abort_unless(self::staff($actor,$a),403);$ids=self::intact($p)?array_column($p->source['basis']['parties'],'id'):[];User::whereIn('id',[$actor->id,...$ids])->orderBy('id')->lockForUpdate()->get();$u=self::actor($actor,$auth);abort_unless(self::staff($u,$a),403);if($p->state!=='Draft'||$p->version!==$version||!self::current($p,true)||!$p->starts_at->gt(now())||$p->active_slot!==1){self::fail();}$prep=User::find($p->source['preparer']['id']);if(!$prep||!self::staff($prep,$a)||$prep->auth_version!==$p->source['preparer']['auth_version']||self::clashes($p)){self::fail('Preparer authority changed or a named participant already has a published review appointment in this slot.');}$p->version++;$p->state='Published';$p->published_at=now()->setMicrosecond(0);$p->publication=['source_hash'=>$p->source_hash,'version'=>$p->version,'by'=>$u->id,'at'=>$p->published_at->toIso8601String()];$p->save();foreach($p->source['basis']['parties']as$role=>$person){$r=new Party(['appointment_id'=>$p->id,'appointment_version'=>$p->version,'user_id'=>$person['id'],'role'=>$role,'identity_hash'=>$person['identity'],'created_at'=>now()]);$r->proof=self::partyProof($r)+['source_hash'=>$p->source_hash];$r->save();}self::event($p,$u,'appointment_published',['source_hash'=>$p->source_hash,'parties'=>3]);},3);
 }
 public static function cancel(User $actor,int $auth,Appointment $record,int $version,string $note):void {DB::transaction(function()use($actor,$auth,$record,$version,$note):void {$a=Apprentice::whereKey($record->apprentice_id)->lockForUpdate()->firstOrFail();$u=self::actor($actor,$auth);abort_unless(self::staff($u,$a),403);$p=Appointment::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::intact($p)||$p->version!==$version||!in_array($p->state,['Draft','Published'],true)){self::fail();}$scheduled=self::scheduleVersion($p);$p->version++;$p->state='Cancelled';$p->active_slot=null;$p->closure=['state'=>'Cancelled','version'=>$p->version,'source_hash'=>$p->source_hash,'schedule_version'=>$scheduled,'by'=>$u->id,'at'=>now()->toIso8601String(),'note'=>$note];$p->save();self::event($p,$u,'appointment_cancelled',['note'=>$note]);},3);}
 public static function response(Appointment $p,User $u):array {$r=Response::where('appointment_id',$p->id)->where('appointment_version',self::scheduleVersion($p)??0)->where('user_id',$u->id)->first();$valid=false;try{$v=$r?->proof;$valid=$r&&$v&&$v['appointment_id']===$p->id&&$v['appointment_version']===$r->appointment_version&&$v['user_id']===$u->id&&$v['response_version']===$r->response_version&&$v['choice']===$r->choice&&$v['source_hash']===$p->source_hash&&$r->source_hash===$p->source_hash&&$v['at']===$r->responded_at->toIso8601String();}catch(\Throwable){}return ['version'=>$r?->response_version??0,'choice'=>$valid?$r->choice:null,'needs_recheck'=>$r&&!$valid];}
 public static function respond(User $actor,int $auth,Appointment $record,int $version,int $responseVersion,string $choice):void {DB::transaction(function()use($actor,$auth,$record,$version,$responseVersion,$choice):void {$u=self::actor($actor,$auth);$p=Appointment::whereKey($record->id)->lockForUpdate()->firstOrFail();abort_unless(self::visible($u,$p),403);$party=Party::where('appointment_id',$p->id)->where('appointment_version',$p->version)->where('user_id',$u->id)->first();abort_unless($party,403);if(!self::published($p)||!self::current($p,true)||$p->version!==$version||!$p->starts_at->gt(now())||!in_array($choice,self::CHOICES,true)){self::fail('Use the current published future appointment. Availability is not attendance or sign-off.');}$r=Response::where('appointment_id',$p->id)->where('appointment_version',$p->version)->where('user_id',$u->id)->lockForUpdate()->first();if(($r?->response_version??0)!==$responseVersion){self::fail('Your response changed. Reload before answering.');}$r??=new Response(['appointment_id'=>$p->id,'appointment_version'=>$p->version,'user_id'=>$u->id,'created_at'=>now()]);$r->response_version=$responseVersion+1;$r->choice=$choice;$r->source_hash=$p->source_hash;$r->responded_at=now()->setMicrosecond(0);$r->updated_at=now();$r->proof=['appointment_id'=>$p->id,'appointment_version'=>$p->version,'user_id'=>$u->id,'response_version'=>$r->response_version,'choice'=>$choice,'source_hash'=>$p->source_hash,'at'=>$r->responded_at->toIso8601String()];$r->save();self::event($p,$u,'availability_recorded',['choice'=>$choice,'response_version'=>$r->response_version]);},3);}
 public static function availability(Appointment $p):array {$counts=array_fill_keys(self::CHOICES,0);$counts['Not answered']=0;if(!self::current($p)||!self::partiesValid($p)){return ['counts'=>$counts,'all_available'=>false,'current'=>false];}foreach($p->source['basis']['parties']as$person){$u=User::find($person['id']);$r=self::response($p,$u);$counts[$r['choice']??'Not answered']++;}return ['counts'=>$counts,'all_available'=>$counts['Available']===3,'current'=>true];}
 public static function preparation(Appointment $p):array {$a=Apprentice::findOrFail($p->apprentice_id);$cycle=SignedReviews::cycle($a);$r=ProgressReviewDraft::where('apprentice_id',$a->id)->latest('updated_at')->latest('id')->first();return ['cycle'=>$cycle,'draft'=>$r,'training_overlap'=>TrainingSession::where('state','Planned')->whereDate('session_date',$p->starts_at->copy()->setTimezone($p->source['logistics']['timezone'])->toDateString())->where(fn($q)=>$q->whereJsonContains('members',$a->id)->orWhereJsonContains('members',(string)$a->id))->get()->contains(fn($s)=>$s->start_time<$p->source['logistics']['end']&&$s->end_time>$p->source['logistics']['start'])];}
 public static function calendar(Appointment $p):string {if(!self::current($p)||!self::partiesValid($p)||!((self::published($p))||self::closureValid($p)||ReviewMeetingFollowup::reported($p))){self::fail('Current published/cancelled appointment authority is required for calendar download.');}$escape=fn($s)=>str_replace(['\\',"\r","\n",',',';'],['\\\\','', '\\n','\\,','\\;'],$s);$lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//GTA//Private review appointments//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT','UID:'.$p->id.'@gta-portal','DTSTAMP:'.now()->utc()->format('Ymd\THis\Z'),'DTSTART:'.$p->starts_at->utc()->format('Ymd\THis\Z'),'DTEND:'.$p->ends_at->utc()->format('Ymd\THis\Z'),'SEQUENCE:'.$p->version,'STATUS:'.($p->state==='Cancelled'?'CANCELLED':'CONFIRMED'),'SUMMARY:GTA progress review appointment','LOCATION:'.$escape($p->source['logistics']['place']),'DESCRIPTION:Private logistics only. Availability is not attendance or review sign-off. Check the live portal after any change.','END:VEVENT','END:VCALENDAR'];$out=[];foreach($lines as$l){$first=true;while(strlen($l)>($first?75:74)){$limit=$first?75:74;$part=mb_strcut($l,0,$limit,'UTF-8');$out[]=($first?'':' ').$part;$l=substr($l,strlen($part));$first=false;}$out[]=($first?'':' ').$l;}return implode("\r\n",$out)."\r\n";}
}
